namespace pulse::app {
namespace {

#ifndef PULSE_HAS_CONTENT_PACK_CATALOG
constexpr PackRelease kContentPackRelease{L"content", L"0", L"https://invalid/", nullptr, 0};
#endif

bool HashMatches(HANDLE file, const wchar_t* expected) {
    if (!expected || wcslen(expected) != 64) return false;
    BCRYPT_ALG_HANDLE algorithm = nullptr;
    BCRYPT_HASH_HANDLE hash = nullptr;
    if (!BCRYPT_SUCCESS(BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0))) return false;
    bool ok = BCRYPT_SUCCESS(BCryptCreateHash(algorithm, &hash, nullptr, 0, nullptr, 0, 0));
    LARGE_INTEGER zero{};
    ok = ok && SetFilePointerEx(file, zero, nullptr, FILE_BEGIN);
    std::vector<unsigned char> buffer(1 << 20);
    while (ok) {
        DWORD read = 0;
        if (!ReadFile(file, buffer.data(), static_cast<DWORD>(buffer.size()), &read, nullptr)) ok = false;
        else if (!read) break;
        else ok = BCRYPT_SUCCESS(BCryptHashData(hash, buffer.data(), read, 0));
    }
    unsigned char digest[32]{};
    ok = ok && BCRYPT_SUCCESS(BCryptFinishHash(hash, digest, sizeof(digest), 0));
    if (hash) BCryptDestroyHash(hash);
    BCryptCloseAlgorithmProvider(algorithm, 0);
    if (!ok) return false;
    static const wchar_t kHex[] = L"0123456789abcdef";
    for (size_t i = 0; i < 32; ++i) {
        if (towlower(expected[2 * i]) != kHex[digest[i] >> 4] || towlower(expected[2 * i + 1]) != kHex[digest[i] & 15])
            return false;
    }
    return true;
}

std::wstring ModuleDirectory() {
    std::wstring path(32768, L'\0');
    const DWORD n = GetModuleFileNameW(nullptr, path.data(), static_cast<DWORD>(path.size()));
    if (!n || n >= path.size()) return {};
    path.resize(n);
    const size_t slash = path.find_last_of(L"\\/");
    return slash == std::wstring::npos ? std::wstring{} : path.substr(0, slash);
}

struct Verified {
    std::mutex mu;
    std::wstring directory;
    std::vector<HANDLE> held;
    void Release() {
        for (HANDLE h : held) CloseHandle(h);
        held.clear();
        directory.clear();
    }
};

Verified& Cache() {
    static Verified* cache = new Verified;  // outlives every caller; never torn down at exit
    return *cache;
}

} // namespace

const PackRelease& ContentPackRelease() noexcept { return kContentPackRelease; }

uint64_t ContentPackDownloadBytes(const PackRelease& release) noexcept {
    uint64_t total = 0;
    for (size_t i = 0; i < release.file_count; ++i) total += release.files[i].packed_size;
    return total;
}

ContentPackCheck CheckContentPack(const PackRelease& release, const std::wstring& packs_root,
                                  std::vector<HANDLE>* hold) {
    ContentPackCheck check;
    if (!release.file_count || !release.files) {
        check.state = ContentPackState::Unavailable;
        return check;
    }
    if (packs_root.empty()) return check;
    std::wstring version;
    const std::wstring directory = packs::InstalledPackDirectory(packs_root + L"\\" + release.key, &version);
    if (directory.empty()) return check;
    if (version != release.version) {
        check.state = ContentPackState::Outdated;
        return check;
    }
    std::vector<HANDLE> opened;
    bool ok = true;
    for (size_t i = 0; ok && i < release.file_count; ++i) {
        const PackFile& file = release.files[i];
        const std::wstring path = directory + L"\\" + file.name;
        const HANDLE h = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING,
                                     FILE_FLAG_SEQUENTIAL_SCAN, nullptr);
        if (h == INVALID_HANDLE_VALUE) { ok = false; break; }
        opened.push_back(h);
        LARGE_INTEGER size{};
        ok = GetFileSizeEx(h, &size) && static_cast<uint64_t>(size.QuadPart) == file.size &&
             HashMatches(h, file.sha256);
    }
    if (!ok || !hold) {
        for (HANDLE h : opened) CloseHandle(h);
        opened.clear();
    }
    if (!ok) {
        check.state = ContentPackState::Damaged;
        return check;
    }
    if (hold) hold->insert(hold->end(), opened.begin(), opened.end());
    check.state = ContentPackState::Ready;
    check.directory = directory;
    return check;
}

namespace {
// Verifies once and keeps the files open; returns the cached directory.
ContentPackState VerifyCached(std::wstring* directory) {
    const std::wstring module = ModuleDirectory();
    if (!module.empty() && packs::IsRegularFile(module + L"\\Pulse.Content.exe")) return ContentPackState::Bundled;
    const PackRelease& release = ContentPackRelease();
    if (!release.file_count) return ContentPackState::Unavailable;
    Verified& cache = Cache();
    std::lock_guard lock(cache.mu);
    if (cache.directory.empty()) {
        std::vector<HANDLE> hold;
        const ContentPackCheck check = CheckContentPack(release, packs::PacksRoot(), &hold);
        if (check.state != ContentPackState::Ready) return check.state;
        cache.directory = check.directory;
        cache.held = std::move(hold);
        // Pulse.Document.exe takes pdfium.dll from here (hash-pinned there).
        if (!module.empty()) SetEnvironmentVariableW(L"PULSE_PDFIUM_DIR", module.c_str());
    }
    if (directory) *directory = cache.directory;
    return ContentPackState::Ready;
}
} // namespace

ContentPackState QueryContentPackState() { return VerifyCached(nullptr); }

std::wstring LocateContentAgent() {
    std::wstring directory;
    if (VerifyCached(&directory) != ContentPackState::Ready) return {};
    return directory + L"\\Pulse.Content.exe";
}

void ForgetVerifiedContentPack() {
    Verified& cache = Cache();
    std::lock_guard lock(cache.mu);
    cache.Release();
}

} // namespace pulse::app
